package io.github.rebrowser.ui;
import static org.junit.Assert.*;
import java.util.*;
import org.junit.Test;
import io.github.rebrowser.settings.SettingsRepository;
import io.github.rebrowser.browser.SearchEngines;
/** Actual UI-vocabulary -> canonical complete settings snapshot, not Android lifecycle evidence. */
public final class NativeGeneralSettingsTest {
 private SettingsRepository.Snapshot original(){return new SettingsRepository.Snapshot(7,SearchEngines.Provider.BING,true,true);}
 @Test public void atomicGeneralSavePreservesApplicationsAndIncrementsMetadataOnce(){SettingsRepository.Snapshot base=original();List<SettingsActivity.Change> changes=Arrays.asList(new SettingsActivity.Change("ui.row.general.homepage",SettingsSections.ValueKind.BOUNDED_TEXT,null,"about:blank",4),new SettingsActivity.Change("ui.row.search.engine",SettingsSections.ValueKind.FIXED_OPTION,null,"baidu",4),new SettingsActivity.Change("ui.row.appearance.background",SettingsSections.ValueKind.FIXED_OPTION,null,"white",4),new SettingsActivity.Change("ui.row.general.recent",SettingsSections.ValueKind.BOOLEAN,false,null,4));SettingsRepository.Snapshot result=SettingsActivity.intendedGeneral(base,changes,4);assertEquals(8,result.metadataRevision());assertEquals("about:blank",result.homepage());assertEquals(SearchEngines.Provider.BAIDU,result.searchProvider());assertEquals(SettingsRepository.NewTabBackground.WHITE,result.newTabBackground());assertFalse(result.newTabRecentEnabled());assertTrue(result.desiredEnabled("music"));assertTrue(result.desiredEnabled("outlook"));assertEquals(SearchEngines.Provider.BING,base.searchProvider());}
 @Test public void explicitDeviceCorrectionIsOneGeneralIntentPreservingGlobalDirectionAndApps(){SettingsRepository.Snapshot base=original().withWindowOrientation(SettingsRepository.WindowOrientation.LANDSCAPE);SettingsRepository.Snapshot result=SettingsActivity.intendedGeneral(base,Arrays.asList(new SettingsActivity.Change("ui.row.general.device-type",SettingsSections.ValueKind.FIXED_OPTION,null,"tablet",4)),4);assertEquals(base.metadataRevision()+1,result.metadataRevision());assertEquals(SettingsRepository.DeviceType.TABLET,result.deviceType());assertEquals(SettingsRepository.WindowOrientation.LANDSCAPE,result.windowOrientation());assertEquals(base.homepage(),result.homepage());assertTrue(result.desiredEnabled("music"));assertTrue(result.desiredEnabled("outlook"));assertThrows(IllegalArgumentException.class,()->new SettingsActivity.Change("ui.row.general.device-type",SettingsSections.ValueKind.FIXED_OPTION,null,"trusted-device",4));}
 @Test public void unrelatedGeneralChangeDoesNotSeedDeviceChoiceOrLoseExistingCorrection(){SettingsRepository.Snapshot base=original().withWindowOrientation(SettingsRepository.WindowOrientation.PORTRAIT);List<SettingsActivity.Change> change=Arrays.asList(new SettingsActivity.Change("ui.row.general.recent",SettingsSections.ValueKind.BOOLEAN,false,null,4));SettingsRepository.Snapshot legacy=SettingsActivity.intendedGeneral(base,change,4);assertNull(legacy.deviceType());assertEquals('4',SettingsRepository.CODEC.encode(legacy)[7]);SettingsRepository.Snapshot configured=SettingsActivity.intendedGeneral(base.withDeviceType(SettingsRepository.DeviceType.PHONE),change,4);assertEquals(SettingsRepository.DeviceType.PHONE,configured.deviceType());assertEquals(SettingsRepository.WindowOrientation.PORTRAIT,configured.windowOrientation());assertEquals('5',SettingsRepository.CODEC.encode(configured)[7]);}
 @Test public void wrongOriginalDiskRevisionCannotRetargetChange(){assertThrows(IllegalArgumentException.class,()->SettingsActivity.intendedGeneral(original(),Arrays.asList(new SettingsActivity.Change("ui.row.general.recent",SettingsSections.ValueKind.BOOLEAN,true,null,4)),5));}
 @Test public void duplicateFieldInBatchIsNotLastWriterWins(){SettingsActivity.Change change=new SettingsActivity.Change("ui.row.general.recent",SettingsSections.ValueKind.BOOLEAN,true,null,4);assertThrows(IllegalArgumentException.class,()->SettingsActivity.intendedGeneral(original(),Arrays.asList(change,change),4));}
 @Test public void unsupportedHomepageCannotBecomeSavedOrSearch(){assertThrows(IllegalArgumentException.class,()->SettingsActivity.intendedGeneral(original(),Arrays.asList(new SettingsActivity.Change("ui.row.general.homepage",SettingsSections.ValueKind.BOUNDED_TEXT,null,"javascript:alert(1)",4)),4));}
 @Test public void liveDraftRejectsInvalidHomepageBeforeSpendingSave(){SettingsActivity.EditSession edits=new SettingsActivity.EditSession(4);assertNotNull(edits.setText("ui.row.general.homepage","javascript:alert(1)"));assertFalse(edits.isDirty());assertFalse(edits.attempted());assertNull(edits.setText("ui.row.general.homepage","https://www.baidu.com/"));assertTrue(edits.isDirty());}
 @Test public void emptyNativeBatchOrMissingSnapshotDoesNotSeedAnything(){assertThrows(IllegalArgumentException.class,()->SettingsActivity.intendedGeneral(original(),Collections.emptyList(),4));assertThrows(IllegalArgumentException.class,()->SettingsActivity.intendedGeneral(null,Collections.emptyList(),4));}
 @Test public void booleanProjectionCannotInventSourceOrPermissionSwitch(){assertThrows(IllegalArgumentException.class,()->new SettingsActivity.Observed(Collections.singletonMap("ui.row.source.safety",true),4));assertThrows(IllegalArgumentException.class,()->new SettingsActivity.Observed(Collections.singletonMap("ui.row.permissions.sites",true),4));}
 @Test public void typedOptionAndTextProjectionCannotCrossSchema(){assertThrows(IllegalArgumentException.class,()->new SettingsActivity.Observed(Collections.emptyMap(),Collections.singletonMap("ui.row.general.recent","true"),Collections.emptyMap(),4));assertThrows(IllegalArgumentException.class,()->new SettingsActivity.Observed(Collections.emptyMap(),Collections.emptyMap(),Collections.singletonMap("ui.row.search.engine","bing"),4));}
}
